import { fileURLToPath } from "node:url";
import type { NodePgDatabase } from "drizzle-orm/node-postgres";
import { migrate } from "drizzle-orm/node-postgres/migrator";
import type * as schema from "./schema.js";

/**
 * Committed SQL migrations generated by `drizzle-kit generate`.
 *
 * Resolved from this module rather than `process.cwd()` so the script
 * works from the package directory, the repository root, or `dist`.
 */
export const MIGRATIONS_FOLDER = fileURLToPath(
  new URL("../../drizzle", import.meta.url),
);

/**
 * Applies every pending migration in order.
 *
 * Drizzle records applied migrations in `drizzle.__drizzle_migrations`,
 * so running this twice is a no-op rather than a duplicate `CREATE`. The
 * migrations in this repository are additive; nothing here drops or
 * rewrites existing records.
 */
export async function migrateDatabase(
  db: NodePgDatabase<typeof schema>,
): Promise<void> {
  await migrate(db, { migrationsFolder: MIGRATIONS_FOLDER });
}
